<?php foreach(['ASC','DISTRICT','NATIONAL'] as $level): ?><div class="border rounded p-3 mb-3"><strong><?= e($level) ?></strong><?php foreach($byLevel[$level]??[] as $role): ?><div class="row align-items-center g-2 mt-1"><div class="col-md-5"><div class="form-check"><input class="form-check-input" type="checkbox" name="role_enabled[]" value="<?= e($role['role_code']) ?>" id="role-<?= e($role['role_code']) ?>"><label class="form-check-label" for="role-<?= e($role['role_code']) ?>"><?= e($role['role_name']) ?></label></div></div><div class="col-md-7"><?php if($level==='NATIONAL'): ?><input type="hidden" name="roles[<?= e($role['role_code']) ?>]" value=""><span class="badge bg-secondary">NATIONAL scope</span><?php else: ?><select class="form-select form-select-sm" name="roles[<?= e($role['role_code']) ?>]" data-searchable-select="Search <?= e($level) ?>"><option value="">Select <?= e($level) ?></option><?php foreach($locByType[$level]??[] as $location): ?><option value="<?= e($location['id']) ?>"><?= e($location['dad_number'].' - '.$location['name_en']) ?></option><?php endforeach; ?></select><?php endif; ?></div></div><?php endforeach; ?></div><?php endforeach; ?>
