<script nonce="<?= e(App\Core\SecurityHeaders::nonce()) ?>">document.querySelector('form')?.addEventListener('submit',function(){const enabled=new Set([...this.querySelectorAll('[name="role_enabled[]"]:checked')].map(x=>x.value));this.querySelectorAll('select[name^="roles["]').forEach(s=>{if(!enabled.has(s.name.slice(6,-1)))s.disabled=true});this.querySelectorAll('input[type="hidden"][name^="roles["]').forEach(s=>{if(!enabled.has(s.name.slice(6,-1)))s.disabled=true});});</script>
